function insRow3()
{
var description = new Array();
description[0] = "<tbody><tr><td><p><span class='b_aj'>Texto original de la Ley 769 de 2002:</span></p><p>ART&Iacute;CULO 1. Las normas del presente C&oacute;digo rigen en todo el territorio nacional y regulan la circulaci&oacute;n de los peatones, usuarios, pasajeros, conductores, motociclistas, ciclistas, agentes de tr&aacute;nsito, y veh&iacute;culos por las v&iacute;as p&uacute;blicas o privadas que est&aacute;n abiertas al p&uacute;blico, o en las v&iacute;as privadas, que internamente circulen veh&iacute;culos; as&iacute; como la actuaci&oacute;n y procedimientos de las autoridades de tr&aacute;nsito.</p><p>En desarrollo de lo dispuesto por el art&iacute;culo <A href='constitucion_politica_1991.html#24' >24</A> de la Constituci&oacute;n Pol&iacute;tica, todo colombiano tiene derecho a circular libremente por el territorio nacional, pero est&aacute; sujeto a la intervenci&oacute;n y reglamentaci&oacute;n de las autoridades para garant&iacute;a de la seguridad y comodidad de los habitantes, especialmente de los peatones y de los discapacitados f&iacute;sicos y mentales, para la preservaci&oacute;n de un ambiente sano y la protecci&oacute;n del uso com&uacute;n del espacio p&uacute;blico.</p><p>Le corresponde al Ministerio de Transporte como autoridad suprema de tr&aacute;nsito definir, orientar, vigilar e inspeccionar la ejecuci&oacute;n de la pol&iacute;tica nacional en materia de tr&aacute;nsito.</p><p>Las autoridades de tr&aacute;nsito promover&aacute;n la difusi&oacute;n y el conocimiento de las disposiciones contenidas en este c&oacute;digo.</p><p>Los principios rectores de este c&oacute;digo son: seguridad de los usuarios, calidad, oportunidad, cubrimiento, libertad de acceso, plena identificaci&oacute;n, libre circulaci&oacute;n, educaci&oacute;n y descentralizaci&oacute;n.</p> </td></tr></tbody>";
var z=document.getElementById('Table3').rows[0];
if (z==null) {
              var x=document.getElementById('Table3').insertRow(0)
              var y=x.insertCell(0)
              y.innerHTML=description
             }
else         {
              document.getElementById('Table3').deleteRow(0)
             }
}
